mapper.select:
SELECT et.id, et.`name`, et.theme_id, et.theme_name, et.source_code, et.source_name, et.source_key, et.exam_start_time, et.exam_end_time, et.charge_user_id, et.charge_user_name, et.timed, et.exam_duration, et.exam_duration_unit, et.retake, et.retake_number, et.exam_task_type, et.exam_user_number, et.exam_task_status, et.remark, et.exam_paper_mode as examPaperMode FROM exam_task et LEFT JOIN theme t on et.theme_id = t.id
et.deleted = 0 and et.tenant = #{tenant}
and (et.name like concat('%',#{query.keyword},'%') or t.name like concat('%',#{query.keyword},'%') or et.theme_name like concat('%',#{query.keyword},'%') )
and et.exam_task_type = #{query.examTaskType}
and et.exam_task_status = #{query.examTaskStatus}
and et.theme_id = #{query.themeId}
and et.exam_start_time >= #{query.period.begin}
and et.exam_start_time <= #{query.period.end}
and et.market_tenant = #{query.marketTenant}
order by et.exam_start_time desc

SELECT et.id, et.`name`, et.theme_id, et.theme_name, et.source_code, et.source_name, et.source_key, et.exam_start_time, et.exam_end_time, et.charge_user_id, et.charge_user_name, et.timed, et.exam_duration, et.exam_duration_unit, et.retake, et.retake_number, et.exam_task_type, et.exam_user_number, et.exam_task_status, et.remark, etu.exam_status as user_exam_status, etu.exam_number, etu.score as user_score FROM exam_task et INNER JOIN exam_task_user etu on et.id = etu.exam_task_id
et.deleted = 0 and et.tenant = #{tenant} and et.exam_task_status != 'UNPUBLISHED'
and etu.user_id = #{query.userId}
and ( et.name like concat('%',#{query.keyword},'%') or et.theme_name like concat('%',#{query.keyword},'%') )
and et.id = #{query.id}
and et.exam_task_type = #{query.examTaskType}
and et.exam_task_status = #{query.examTaskStatus}
and et.theme_id = #{query.themeId}
and et.exam_start_time >= #{query.period.begin}
and et.exam_start_time <= #{query.period.end}
and etu.user_id = #{query.userId}
order by published_time desc

SELECT t.id, t.`name`, t.theme_id, t.theme_name, t.source_code, t.source_name, t.source_key, t.exam_start_time, t.exam_end_time, t.charge_user_id, t.charge_user_name, t.timed, t.exam_duration, t.exam_duration_unit, t.retake, t.retake_number, t.exam_task_type, t.exam_user_number, t.exam_task_status, t.remark, t.user_exam_status, t.exam_number, t.user_score FROM ( SELECT et.id, et.`name`, et.theme_id, et.theme_name, et.source_code, et.source_name, et.source_key, et.exam_start_time, et.exam_end_time, et.charge_user_id, et.charge_user_name, et.timed, et.exam_duration, et.exam_duration_unit, et.retake, et.retake_number, et.exam_task_type, et.exam_user_number, et.exam_task_status, et.remark, NULL AS user_exam_status, NULL AS exam_number, NULL AS user_score, et.published_time FROM exam_task et WHERE et.deleted = 0 and et.exam_task_status != 'UNPUBLISHED' AND ( SELECT COUNT( 1 ) FROM exam_task_user WHERE exam_task_id = et.id AND user_identify = #{query.userIdentify} ) <= 0
and et.tenant = #{query.tenant}
and et.market_tenant = #{query.marketTenant}
and ( et.name like concat('%',#{query.keyword},'%') or et.theme_name like concat('%',#{query.keyword},'%') )
and et.exam_task_type = #{query.examTaskType}
and et.exam_task_status = #{query.examTaskStatus}
and et.theme_id = #{query.themeId}
and et.exam_start_time >= #{query.period.begin}
and et.exam_start_time <= #{query.period.end}
GROUP BY et.id UNION SELECT et.id, et.`name`, et.theme_id, et.theme_name, et.source_code, et.source_name, et.source_key, et.exam_start_time, et.exam_end_time, et.charge_user_id, et.charge_user_name, et.timed, et.exam_duration, et.exam_duration_unit, et.retake, et.retake_number, et.exam_task_type, et.exam_user_number, et.exam_task_status, et.remark, etu.exam_status AS user_exam_status, etu.exam_number, etu.score AS user_score, et.published_time FROM exam_task et INNER JOIN exam_task_user etu ON et.id = etu.exam_task_id
et.deleted = 0 and et.exam_task_status != 'UNPUBLISHED' and etu.user_identify = #{query.userIdentify}
and et.tenant = #{query.tenant}
and et.market_tenant = #{query.marketTenant}
and ( et.name like concat('%',#{query.keyword},'%') or et.theme_name like concat('%',#{query.keyword},'%') )
and et.exam_task_type = #{query.examTaskType}
and et.exam_task_status = #{query.examTaskStatus}
and et.theme_id = #{query.themeId}
and et.exam_start_time >= #{query.period.begin}
and et.exam_start_time <= #{query.period.end}
GROUP BY et.id ) t ORDER BY t.published_time desc

SELECT et.id, et.`name`, et.theme_id, et.theme_name, et.exam_start_time, et.exam_end_time, et.exam_paper_id, et.exam_paper_name, et.charge_user_id, et.charge_user_name, et.timed, et.exam_duration, et.exam_duration_unit, et.retake, et.retake_number, et.exam_task_type, et.exam_paper_mode as examPaperMode, et.exam_user_number, et.exam_task_status, et.remark, et.tenant, et.deleted, et.create_by, et.creator_id, et.creator_type, et.create_time, et.update_by, et.update_time FROM exam_task et
et.deleted = 0 and et.tenant = #{tenant}
and (et.name like concat('%',#{query.keyword},'%') or t.name like concat('%',#{query.keyword},'%') )
and et.exam_task_type = #{query.examTaskType}
and et.exam_task_status = #{query.examTaskStatus}
and et.theme_id = #{query.themeId}
and et.update_time >= #{query.period.begin}
and et.update_time <= #{query.period.end}
order by et.exam_start_time desc

SELECT et.id, et.`name`, et.theme_id, et.theme_name, et.exam_start_time, et.exam_end_time, et.charge_user_id, et.charge_user_name, et.exam_task_type, et.exam_user_number, et.remark, COALESCE ( sum( IF ( etu.exam_status = 'EXAMINED', 1, 0 )), 0 ) AS reality_exam_user_number, COALESCE ( sum( IF ( etu.exam_status = 'MISS_EXAM', 1, 0 )), 0 ) AS miss_exam_user_number, COALESCE ( sum( IF ( etu.passed = 0, 1, 0 )), 0 ) AS no_passed_user_number, SUM(etu.score) as total_score FROM `exam_task` et INNER JOIN exam_task_user etu ON et.id = etu.exam_task_id
et.exam_task_status = 'ENDED' and et.tenant = #{tenant}
and ( et.name like concat('%',#{query.keyword},'%') or et.theme_name like concat('%',#{query.keyword},'%') )
and et.exam_task_type = #{query.examTaskType}
and et.theme_id = #{query.themeId}
and et.exam_start_time >= #{query.period.begin}
and et.exam_start_time <= #{query.period.end}
and etu.user_department_id = #{query.organizationId}
and et.id in
#{id}
group by et.id order by et.exam_end_time desc

SELECT et.id, et.`name`, et.theme_id, et.theme_name, et.exam_start_time, et.exam_end_time, et.charge_user_id, et.charge_user_name, et.exam_task_type, et.exam_user_number, et.remark, COALESCE ( sum( IF ( etu.exam_status = 'EXAMINED', 1, 0 )), 0 ) AS reality_exam_user_number, COALESCE ( sum( IF ( etu.exam_status = 'MISS_EXAM', 1, 0 )), 0 ) AS miss_exam_user_number, COALESCE ( sum( IF ( etu.passed = 0, 1, 0 )), 0 ) AS no_passed_user_number, SUM(etu.score) as total_score FROM `exam_task` et INNER JOIN exam_task_user etu ON et.id = etu.exam_task_id
et.exam_task_status = 'ENDED' and et.tenant = #{tenant}
and ( et.name like concat('%',#{query.keyword},'%') or et.theme_name like concat('%',#{query.keyword},'%') )
and et.exam_task_type = #{query.examTaskType}
and et.theme_id = #{query.themeId}
and et.exam_start_time >= #{query.period.begin}
and et.exam_start_time <= #{query.period.end}
and et.id in
#{id}
group by et.id order by et.exam_end_time desc

SELECT et.id, et.`name`, et.theme_id, et.theme_name, et.exam_start_time, et.exam_end_time, et.charge_user_id, et.charge_user_name, et.exam_task_type, et.exam_user_number, et.remark, COALESCE ( sum( IF ( etu.exam_status = 'EXAMINED', 1, 0 )), 0 ) AS reality_exam_user_number, COALESCE ( sum( IF ( etu.exam_status = 'MISS_EXAM', 1, 0 )), 0 ) AS miss_exam_user_number, COALESCE ( sum( IF ( etu.passed = 0, 1, 0 )), 0 ) AS no_passed_user_number, SUM(etu.score) as total_score FROM `exam_task` et INNER JOIN exam_task_user etu ON et.id = etu.exam_task_id
et.exam_task_status = 'ENDED' and et.tenant = #{tenant}
and ( et.name like concat('%',#{query.keyword},'%') or et.theme_name like concat('%',#{query.keyword},'%') )
and et.exam_task_type = #{query.examTaskType}
and et.theme_id = #{query.themeId}
and et.exam_start_time >= #{query.period.begin}
and et.exam_start_time <= #{query.period.end}
and et.id in
#{id}
group by et.id order by et.exam_end_time desc

SELECT
et.theme_id as id,
et.theme_name as `name` ,
COUNT(id) as total_num
FROM
exam_task et

    ((et.exam_task_status = 'ENDED') or (et.deleted = 0)) and et.tenant = #{tenant}

        and et.exam_start_time >= #{query.period.begin}


        and et.exam_start_time <= #{query.period.end}


GROUP BY theme_id

SELECT
et.exam_task_type,
COUNT(et.id) as total_num
FROM
exam_task et

    ((et.exam_task_status = 'ENDED') or (et.deleted = 0)) and et.tenant = #{tenant}

        and et.exam_start_time >= #{query.period.begin}


        and et.exam_start_time <= #{query.period.end}


GROUP BY exam_task_type

SELECT et.id, et.`name`, et.exam_user_number, COALESCE ( sum( IF ( etu.exam_status = 'MISS_EXAM', 1, 0 )), 0 ) AS miss_exam_user_number, COALESCE ( sum( IF ( etu.passed = 0, 1, 0 )), 0 ) AS no_passed_user_number FROM `exam_task` et INNER JOIN exam_task_user etu ON et.id = etu.exam_task_id
et.exam_task_status = 'ENDED' and et.tenant = #{tenant}
and et.exam_start_time >= #{query.period.begin}
and et.exam_start_time <= #{query.period.end}
GROUP BY et.id order by et.exam_end_time desc

SELECT DATE_FORMAT( et.exam_start_time, '%Y-%m' ) AS `name`, count(*) AS num FROM exam_task et
((et.exam_task_status = 'ENDED') or (et.deleted = 0)) and et.tenant = #{tenant}
and et.exam_start_time >= #{query.period.begin}
and et.exam_start_time <= #{query.period.end}
GROUP BY DATE_FORMAT( et.exam_start_time, '%Y-%m')

SELECT
count(DISTINCT et.id) as total_num
FROM
`exam_task` et
LEFT JOIN exam_task_user etu on et.id = etu.exam_task_id

    ((et.exam_task_status = 'ENDED') or (et.deleted = 0)) and et.tenant = #{tenant}

        and et.exam_start_time >= #{query.period.begin}


        and et.exam_start_time <= #{query.period.end}

SELECT
COALESCE ( sum( IF ( etu.passed = 0, 1, 0 )), 0 ) AS no_passed_user_number
FROM
`exam_task` et
INNER JOIN exam_task_user etu ON et.id = etu.exam_task_id

    et.exam_task_status = 'ENDED' and et.tenant = #{tenant}

        and et.exam_start_time >= #{query.period.begin}


        and et.exam_start_time <= #{query.period.end}

SELECT
COALESCE ( sum( IF ( etu.exam_status = 'MISS_EXAM', 1, 0 )), 0 ) AS miss_exam_user_number
FROM
`exam_task` et
INNER JOIN exam_task_user etu ON et.id = etu.exam_task_id

    et.exam_task_status = 'ENDED' and et.tenant = #{tenant}

        and et.exam_start_time >= #{query.period.begin}


        and et.exam_start_time <= #{query.period.end}

SELECT et.theme_id as id, et.theme_name as `name` , COUNT(DISTINCT et.id) as total_num FROM exam_task et LEFT JOIN exam_task_user etu ON et.id = etu.exam_task_id
et.tenant = #{tenant} and et.deleted = 0
and et.exam_start_time >= #{query.period.begin}
and et.exam_start_time <= #{query.period.end}
GROUP BY theme_id

SELECT COUNT(id) as total_num FROM exam_task et
et.tenant = #{tenant} and et.deleted = 0
and et.exam_start_time >= #{query.period.begin}
and et.exam_start_time <= #{query.period.end}

SELECT COUNT( DISTINCT et.user_identify ) FROM exam_task_user et
et.deleted = 0
and et.create_time >= #{query.period.begin}
and et.create_time <= #{query.period.end}

SELECT COUNT(t1.id) as task_count FROM `exam_task` t1 INNER JOIN exam_task_paper t2 on t1.id = t2.exam_task_id
t1.deleted = 0 and t1.exam_task_status in ('STAY_EXAM','IN_PROGRESS') and t2.user_identify is null and t2.exam_paper_id in
#{paperId}
